//! The glyphs of the neume font (`assets/fonts/gabc-neumes.ttf`) with their code points and
//! sizes. Generated by `cargo run -p xtask -- font` from the exsurge glyph table; do not edit.
//!
//! Lengths are in em. One em is four staff spaces, so a staff step (from a line to the space
//! next to it) is 0.125 em. A glyph is placed by its origin: the left end of its ink, at
//! the height of the note it stands for.

/// A glyph of the neume font.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum Glyph {
    AcuteAccent,
    Stropha,
    BeginningAscLiquescent,
    BeginningDesLiquescent,
    CustosDescLong,
    CustosDescShort,
    CustosLong,
    CustosShort,
    DoClef,
    FaClef,
    Flat,
    Mora,
    Natural,
    OriscusAsc,
    OriscusDes,
    OriscusLiquescent,
    PodatusLower,
    PodatusUpper,
    Porrectus1,
    Porrectus2,
    Porrectus3,
    Porrectus4,
    PunctumCavum,
    PunctumQuadratum,
    PunctumQuadratumAscLiquescent,
    PunctumQuadratumDesLiquescent,
    PunctumInclinatum,
    PunctumInclinatumLiquescent,
    Quilisma,
    TerminatingAscLiquescent,
    TerminatingDesLiquescent,
    VerticalEpisemaAbove,
    VerticalEpisemaBelow,
    VirgaLong,
    VirgaShort,
    Virgula,
}

/// The size of a glyph, in em.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Metrics {
    /// How wide the ink is, which is also the advance.
    pub width: f32,
    /// How far the ink reaches above the origin.
    pub above: f32,
    /// How far the ink reaches below the origin.
    pub below: f32,
    /// True for a glyph that is set with its right edge against what stands before it
    /// (the upper note of a podatus sits on top of the lower one).
    pub align_right: bool,
}

impl Glyph {
    /// The character of the glyph in the font, in the private use area.
    pub fn char(self) -> char {
        match self {
            Glyph::AcuteAccent => '\u{E000}',
            Glyph::Stropha => '\u{E001}',
            Glyph::BeginningAscLiquescent => '\u{E002}',
            Glyph::BeginningDesLiquescent => '\u{E003}',
            Glyph::CustosDescLong => '\u{E004}',
            Glyph::CustosDescShort => '\u{E005}',
            Glyph::CustosLong => '\u{E006}',
            Glyph::CustosShort => '\u{E007}',
            Glyph::DoClef => '\u{E008}',
            Glyph::FaClef => '\u{E009}',
            Glyph::Flat => '\u{E00A}',
            Glyph::Mora => '\u{E00B}',
            Glyph::Natural => '\u{E00C}',
            Glyph::OriscusAsc => '\u{E00D}',
            Glyph::OriscusDes => '\u{E00E}',
            Glyph::OriscusLiquescent => '\u{E00F}',
            Glyph::PodatusLower => '\u{E010}',
            Glyph::PodatusUpper => '\u{E011}',
            Glyph::Porrectus1 => '\u{E012}',
            Glyph::Porrectus2 => '\u{E013}',
            Glyph::Porrectus3 => '\u{E014}',
            Glyph::Porrectus4 => '\u{E015}',
            Glyph::PunctumCavum => '\u{E016}',
            Glyph::PunctumQuadratum => '\u{E017}',
            Glyph::PunctumQuadratumAscLiquescent => '\u{E018}',
            Glyph::PunctumQuadratumDesLiquescent => '\u{E019}',
            Glyph::PunctumInclinatum => '\u{E01A}',
            Glyph::PunctumInclinatumLiquescent => '\u{E01B}',
            Glyph::Quilisma => '\u{E01C}',
            Glyph::TerminatingAscLiquescent => '\u{E01D}',
            Glyph::TerminatingDesLiquescent => '\u{E01E}',
            Glyph::VerticalEpisemaAbove => '\u{E01F}',
            Glyph::VerticalEpisemaBelow => '\u{E020}',
            Glyph::VirgaLong => '\u{E021}',
            Glyph::VirgaShort => '\u{E022}',
            Glyph::Virgula => '\u{E023}',
        }
    }

    pub fn metrics(self) -> Metrics {
        let m = |width, above, below, align_right| Metrics { width, above, below, align_right };
        match self {
            Glyph::AcuteAccent => m(0.13874, 0.15659, 0.00065, false),
            Glyph::Stropha => m(0.12207, 0.09180, 0.09766, false),
            Glyph::BeginningAscLiquescent => m(0.12500, 0.11043, 0.08000, false),
            Glyph::BeginningDesLiquescent => m(0.12500, 0.09445, 0.09500, false),
            Glyph::CustosDescLong => m(0.05794, 0.08199, 0.34249, false),
            Glyph::CustosDescShort => m(0.05469, 0.08236, 0.25520, false),
            Glyph::CustosLong => m(0.05794, 0.33760, 0.08687, false),
            Glyph::CustosShort => m(0.05469, 0.25046, 0.08711, false),
            Glyph::DoClef => m(0.12500, 0.20610, 0.20797, false),
            Glyph::FaClef => m(0.24219, 0.19625, 0.22074, false),
            Glyph::Flat => m(0.12240, 0.25551, 0.07945, false),
            Glyph::Mora => m(0.06000, 0.03000, 0.03000, false),
            Glyph::Natural => m(0.08789, 0.20820, 0.20488, false),
            Glyph::OriscusAsc => m(0.12500, 0.09500, 0.08957, false),
            Glyph::OriscusDes => m(0.12500, 0.09426, 0.09031, false),
            Glyph::OriscusLiquescent => m(0.12500, 0.09426, 0.09031, false),
            Glyph::PodatusLower => m(0.12500, 0.05250, 0.07640, false),
            Glyph::PodatusUpper => m(0.11426, 0.07973, 0.07750, true),
            Glyph::Porrectus1 => m(0.37793, 0.06594, 0.20360, false),
            Glyph::Porrectus2 => m(0.47168, 0.08594, 0.32422, false),
            Glyph::Porrectus3 => m(0.47168, 0.08750, 0.44668, false),
            Glyph::Porrectus4 => m(0.52500, 0.08750, 0.56973, false),
            Glyph::PunctumCavum => m(0.12500, 0.07613, 0.07816, false),
            Glyph::PunctumQuadratum => m(0.12500, 0.07613, 0.07816, false),
            Glyph::PunctumQuadratumAscLiquescent => m(0.12500, 0.11043, 0.08000, false),
            Glyph::PunctumQuadratumDesLiquescent => m(0.12500, 0.09445, 0.09500, false),
            Glyph::PunctumInclinatum => m(0.12500, 0.09472, 0.09375, false),
            Glyph::PunctumInclinatumLiquescent => m(0.08750, 0.06646, 0.06548, false),
            Glyph::Quilisma => m(0.12500, 0.11160, 0.07590, false),
            Glyph::TerminatingAscLiquescent => m(0.06250, 0.06105, 0.09129, true),
            Glyph::TerminatingDesLiquescent => m(0.06250, 0.10121, 0.05211, true),
            Glyph::VerticalEpisemaAbove => m(0.02000, 0.10000, 0.00000, false),
            Glyph::VerticalEpisemaBelow => m(0.02000, 0.00000, 0.10000, false),
            Glyph::VirgaLong => m(0.12500, 0.08363, 0.32457, false),
            Glyph::VirgaShort => m(0.12500, 0.08363, 0.23278, false),
            Glyph::Virgula => m(0.12252, 0.11108, 0.10795, false),
        }
    }
}
